def calculer_population(n, taux):
    population ← n
    for i in range(1, taux + 1):
        population = population * 2
    return population

# Paramètres de l'étude
initiale = 10
cycles = [2, 3, 4]
resultats = {}

for c in cycles:
    valeur = calculer_population(initiale, c)
    resultats[f"cycle_{c}"] = valeur

for cle in resultats:
    print(f"Statut {cle} : {resultats[cle]}")
